using MediatR; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using VetCommission.Application.Features.Clinics; using VetCommission.WebApi.Auth; using VetCommission.WebApi.Extensions;
namespace VetCommission.WebApi.Controllers;
[ApiController,Route("api/clinicas"),Authorize(Policy=AuthorizationPolicyNames.ClinicsManage)] public sealed class ClinicsController(IMediator mediator):ControllerBase
{ [HttpGet] public async Task<IActionResult> List([FromQuery]int page=1,[FromQuery]int pageSize=20,[FromQuery]string? busca=null,[FromQuery]bool? ativo=null,CancellationToken c=default)=>(await mediator.Send(new ListClinicsQuery(page,pageSize,busca,ativo),c)).ToActionResult(this); [HttpGet("{id:guid}")] public async Task<IActionResult> Get(Guid id,CancellationToken c)=>(await mediator.Send(new GetClinicQuery(id),c)).ToActionResult(this); [HttpPost] public async Task<IActionResult> Create(SaveClinicCommand command,CancellationToken c)=>(await mediator.Send(command,c)).ToActionResult(this); [HttpPut("{id:guid}")] public async Task<IActionResult> Update(Guid id,SaveClinicRequest request,CancellationToken c)=>(await mediator.Send(new SaveClinicCommand(id,request.Name,request.LegalName,request.Document,request.Email,request.Phone),c)).ToActionResult(this); [HttpPost("{id:guid}/ativar")] public async Task<IActionResult> Activate(Guid id,CancellationToken c)=>(await mediator.Send(new SetClinicActiveCommand(id,true),c)).ToActionResult(this); [HttpPost("{id:guid}/inativar")] public async Task<IActionResult> Deactivate(Guid id,CancellationToken c)=>(await mediator.Send(new SetClinicActiveCommand(id,false),c)).ToActionResult(this); public sealed record SaveClinicRequest(string Name,string? LegalName,string? Document,string? Email,string? Phone); }
